n Virginia","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Clause Representation","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/appraisal-demand-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Homeowners Insurance Appraisal","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/homeowners-insurance-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Claim Appraisal","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/commercial-and-hoa-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/hail-and-roof-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wind & Tornado Damage Appraisal","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/windstorm-and-tornado-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hurricane & Nor’easter Appraisal","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/hurricane-and-noreaster-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Claim Appraisal","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/water-damage-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/fire-and-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fallen Tree & Ice Storm Appraisal","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/tree-fall-and-ice-storm-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Historic Home Claim Appraisal","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/historic-home-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Selection & Services","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/umpire-selection-and-services/"}}]},"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://virginiainsuranceappraiser.com/#website","url":"https://virginiainsuranceappraiser.com/","name":"Virginia Insurance Appraiser","publisher":{"@id":"https://virginiainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://virginiainsuranceappraiser.com/virginia-appraisal-questions/#webpage","url":"https://virginiainsuranceappraiser.com/virginia-appraisal-questions/","name":"Virginia Insurance Appraisal FAQ | Grouped by Topic","description":"Virginia insurance appraisal FAQ grouped by topic: how appraisal works, costs, deadlines, the Bureau of Insurance and working with us.","inLanguage":"en-US","isPartOf":{"@id":"https://virginiainsuranceappraiser.com/#website"},"about":{"@id":"https://virginiainsuranceappraiser.com/#business"},"publisher":{"@id":"https://virginiainsuranceappraiser.com/#business"},"dateModified":"2026-11-14","breadcrumb":{"@id":"https://virginiainsuranceappraiser.com/virginia-appraisal-questions/#breadcrumb"},"primaryImageOfPage":{"@id":"https://virginiainsuranceappraiser.com/virginia-appraisal-questions/#primaryimage"},"mainEntity":{"@id":"https://virginiainsuranceappraiser.com/virginia-appraisal-questions/#faq"}},{"@type":"ImageObject","@id":"https://virginiainsuranceappraiser.com/virginia-appraisal-questions/#primaryimage","url":"https://virginiainsuranceappraiser.com/assets/img/photos/consult-table.webp","width":1024,"height":683,"caption":"Two people in business attire at a white table with a laptop, one writing on a document on a clipboard while the other gestures."},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"It’s a process written into most property policies for resolving disagreements about the amount of a covered loss. Each side names an appraiser, the appraisers pick an umpire, and an award signed by two of the three sets the amount."}},{"@type":"Question","name":"Is appraisal the same as arbitration?","acceptedAnswer":{"@type":"Answer","text":"Not exactly. Appraisal is limited to the amount of loss and is usually less formal than arbitration. It doesn’t decide coverage or legal claims."}},{"@type":"Question","name":"Can appraisal decide whether my damage is covered?","acceptedAnswer":{"@type":"Answer","text":"Generally no. Appraisers decide how much a loss costs. Whether something is covered is a legal question for the insurer, and if necessary a court, to decide."}},{"@type":"Question","name":"Who can demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Under most policies, either the policyholder or the insurer can demand it in writing once the two sides disagree on the amount of loss."}},{"@type":"Question","name":"What does an appraiser cost?","acceptedAnswer":{"@type":"Answer","text":"Arrangements vary: flat fees, hourly rates or a percentage of the increase. We put our fee in writing before any work starts, and the first conversation is free."}},{"@type":"Question","name":"Who pays the umpire?","acceptedAnswer":{"@type":"Answer","text":"Most appraisal clauses split the umpire’s fee equally between you and the insurer. Each side pays its own appraiser."}},{"@type":"Question","name":"Is appraisal worth it on a small claim?","acceptedAnswer":{"@type":"Answer","text":"Often not. When the gap is small, fees can absorb the recovery. A documented supplement request or an estimate review may close it more cheaply."}},{"@type":"Question","name":"How long does appraisal take?","acceptedAnswer":{"@type":"Answer","text":"Many residential files finish within six to twelve weeks after both appraisers are named. Complex commercial files or umpire hearings take longer."}},{"@type":"Question","name":"Does appraisal stop my deadline to sue?","acceptedAnswer":{"@type":"Answer","text":"Not automatically. Some policies or agreements address it; many don’t. Track the suit-limitation date separately and talk to a Virginia attorney if it’s getting close."}},{"@type":"Question","name":"How long do I have to file suit in Virginia?","acceptedAnswer":{"@type":"Answer","text":"Virginia’s standard fire policy provisions commonly give two years from the date of loss, but your policy’s ‘Suit Against Us’ clause controls. Confirm the date with an attorney."}},{"@type":"Question","name":"When should I demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"After the scope is fully documented and you have both estimates, but well before any policy deadline. Demanding too early is a common mistake."}},{"@type":"Question","name":"Who regulates insurance companies in Virginia?","acceptedAnswer":{"@type":"Answer","text":"The Bureau of Insurance, part of the State Corporation Commission (SCC). It licenses insurers, agents and public adjusters and takes consumer complaints."}},{"@type":"Question","name":"What is the VPIA?","acceptedAnswer":{"@type":"Answer","text":"The Virginia Property Insurance Association is Virginia’s FAIR Plan, a market of last resort for owners who can’t find property coverage in the voluntary market."}},{"@type":"Question","name":"Does Virginia have a bad-faith law?","acceptedAnswer":{"@type":"Answer","text":"Virginia Code § 38.2-209 lets a court award a policyholder costs and reasonable attorney’s fees in certain cases where it finds an insurer denied coverage or refused to pay in bad faith. Section 38.2-510 lists unfair claim settlement practices the Bureau of Insurance enforces. These are legal matters for an attorney, not an appraiser."}},{"@type":"Question","name":"Is an appraiser the same as a public adjuster?","acceptedAnswer":{"@type":"Answer","text":"No. Public adjusters are licensed by the Bureau of Insurance to handle and negotiate claims for policyholders. An appraiser works within the appraisal clause on the amount of loss. We are not public adjusters."}},{"@type":"Question","name":"What do you need from me to start?","acceptedAnswer":{"@type":"Answer","text":"Your declarations page, the insurer’s full estimate, any letters or emails, and photos. Your contractor’s estimate helps if you have one."}},{"@type":"Question","name":"Do you work outside the big cities?","acceptedAnswer":{"@type":"Answer","text":"Yes. We work statewide across Virginia’s 95 counties and 38 independent cities, from the Eastern Shore to Lee County."}},{"@type":"Question","name":"Do you give legal advice?","acceptedAnswer":{"@type":"Answer","text":"No. We’re not a law firm. If your claim involves a denial, a coverage question or a deadline that’s about to run, we’ll suggest you speak with a Virginia attorney."}},{"@type":"Question","name":"Can you guarantee a result?","acceptedAnswer":{"@type":"Answer","text":"No honest appraiser can. We can promise a careful, documented valuation and a straight answer about whether appraisal makes sense."}}],"@id":"https://virginiainsuranceappraiser.com/virginia-appraisal-questions/#faq"},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://virginiainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal FAQ","item":"https://virginiainsuranceappraiser.com/virginia-appraisal-questions/"}],"@id":"https://virginiainsuranceappraiser.com/virginia-appraisal-questions/#breadcrumb"}]}</script>
